<?php
require_once '_bootstrap.php';
require_admin();
$db=admin_db();
ensure_app_schema($db);
$period=$_GET['period']??'monthly';if(!in_array($period,['monthly','quarterly','yearly'],true))$period='monthly';$year=filter_input(INPUT_GET,'year',FILTER_VALIDATE_INT)?:0;$yearWhere=$year?' AND YEAR(p.created_at)='.(int)$year:'';
$periodExpression=$period==='yearly'?"DATE_FORMAT(p.created_at,'%Y')":($period==='quarterly'?"CONCAT(YEAR(p.created_at),' Q',QUARTER(p.created_at))":"DATE_FORMAT(p.created_at,'%Y-%m')");
$financial=$db->query("SELECT $periodExpression period_label,COUNT(DISTINCT p.booking_id) bookings,SUM(p.status='paid') paid_transactions,COALESCE(SUM(CASE WHEN p.status='paid' THEN p.amount ELSE 0 END),0) collected,COALESCE(SUM(CASE WHEN p.status='refunded' THEN -p.amount ELSE 0 END),0) refunds,COALESCE(SUM(CASE WHEN p.status IN ('paid','refunded') THEN p.amount ELSE 0 END),0) net_revenue FROM payments p WHERE p.status IN ('paid','refunded')$yearWhere GROUP BY period_label ORDER BY MIN(p.created_at) DESC");
$financialRows=$financial->fetch_all(MYSQLI_ASSOC);$maxChart=max(array_map(static fn($row)=>(float)$row['collected'],$financialRows)?:[1]);
if(($_GET['export']??'')==='csv'){while(ob_get_level())ob_end_clean();$filename='travel-india-financial-'.$period.($year?'-'.$year:'').'.csv';header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="'.$filename.'"');header('Cache-Control: no-store, no-cache, must-revalidate');header('X-Content-Type-Options: nosniff');$output=fopen('php://output','wb');fwrite($output,"\xEF\xBB\xBF");fputcsv($output,['Period','Bookings','Paid transactions','Collected INR','Refunded INR','Net revenue INR'],',','"','');foreach($financialRows as $row)fputcsv($output,[$row['period_label'],$row['bookings'],$row['paid_transactions'],$row['collected'],$row['refunds'],$row['net_revenue']],',','"','');fclose($output);exit;}
$destinations=$db->query("SELECT b.destination,COUNT(*) bookings,SUM(b.people) travellers,SUM(b.total_amount) booked_value,SUM(COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.booking_id=b.id AND p.status IN ('paid','refunded')),0)) net_revenue FROM bookings b GROUP BY b.destination ORDER BY bookings DESC LIMIT 10");
$themes=$db->query("SELECT trip_theme,COUNT(*) bookings,SUM(people) travellers FROM bookings GROUP BY trip_theme ORDER BY bookings DESC");
$mealPlans=$db->query("SELECT meal_plan_name,COUNT(*) bookings,SUM(people) travellers,SUM(meal_surcharge_total) upgrade_revenue FROM bookings GROUP BY meal_plan_name ORDER BY bookings DESC");
$foodPreferences=$db->query("SELECT food_preference,COUNT(*) travellers,SUM(dietary_notes IS NOT NULL AND dietary_notes<>'') dietary_notes FROM booking_travellers GROUP BY food_preference ORDER BY travellers DESC");
$pageTitle='Reports';
include '_header.php';
?>
<link rel="stylesheet" href="../css/admin-reports.css?v=1">
<div class="page-head"><div><span>India tourism management information</span><h1>Reports</h1></div><div class="report-actions"><button class="primary-btn" onclick="window.print()"><i class="fa-solid fa-print"></i> Print</button><a class="reset-btn" href="?<?php echo e(http_build_query(['period'=>$period,'year'=>$year?:null,'export'=>'csv']));?>"><i class="fa-solid fa-file-csv"></i> Export CSV</a></div></div>
<form class="report-filter" method="get"><label>Report period<select name="period"><option value="monthly" <?php echo $period==='monthly'?'selected':'';?>>Monthly</option><option value="quarterly" <?php echo $period==='quarterly'?'selected':'';?>>Quarterly</option><option value="yearly" <?php echo $period==='yearly'?'selected':'';?>>Yearly</option></select></label><label>Calendar year<input type="number" name="year" min="2000" max="2100" value="<?php echo $year?:'';?>" placeholder="All years"></label><button class="primary-btn"><i class="fa-solid fa-filter"></i> Apply</button><a class="reset-btn" href="reports.php"><i class="fa-solid fa-rotate-left"></i> Reset</a></form>
<div class="report-grid">
<section class="panel report-wide"><div class="panel-head"><h2><?php echo e(ucfirst($period));?> financial performance</h2></div><div class="financial-chart" role="img" aria-label="Collected, refunded, and net revenue by period"><?php foreach(array_reverse($financialRows) as $r):?><div class="chart-group"><b><?php echo e($r['period_label']);?></b><div><span class="chart-collected" style="--bar:<?php echo $maxChart>0?round((float)$r['collected']/$maxChart*100,2):0;?>%" title="Collected <?php echo e(inr($r['collected']));?>"></span><span class="chart-refund" style="--bar:<?php echo $maxChart>0?round((float)$r['refunds']/$maxChart*100,2):0;?>%" title="Refunded <?php echo e(inr($r['refunds']));?>"></span><span class="chart-net" style="--bar:<?php echo $maxChart>0?round(max(0,(float)$r['net_revenue'])/$maxChart*100,2):0;?>%" title="Net <?php echo e(inr($r['net_revenue']));?>"></span></div></div><?php endforeach;?></div><div class="chart-legend"><span><i class="collected"></i>Collected</span><span><i class="refunded"></i>Refunded</span><span><i class="net"></i>Net revenue</span></div><div class="table-wrap"><table><thead><tr><th>Period</th><th>Bookings</th><th>Paid transactions</th><th>Collected</th><th>Refunded</th><th>Net revenue</th></tr></thead><tbody><?php foreach($financialRows as $r):?><tr><td><?php echo e($r['period_label']);?></td><td><?php echo (int)$r['bookings'];?></td><td><?php echo (int)$r['paid_transactions'];?></td><td><?php echo inr($r['collected']);?></td><td><?php echo inr($r['refunds']);?></td><td><strong><?php echo inr($r['net_revenue']);?></strong></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel"><div class="panel-head"><h2>Top Indian destinations</h2></div><div class="table-wrap"><table><thead><tr><th>Destination</th><th>Bookings</th><th>Travellers</th><th>Booked value (INR)</th><th>Net revenue (INR)</th></tr></thead><tbody><?php while($r=$destinations->fetch_assoc()):?><tr><td><?php echo e($r['destination']);?></td><td><?php echo (int)$r['bookings'];?></td><td><?php echo (int)$r['travellers'];?></td><td><?php echo inr($r['booked_value']);?></td><td><?php echo inr($r['net_revenue']);?></td></tr><?php endwhile;?></tbody></table></div></section>
<section class="panel"><div class="panel-head"><h2>Bookings by trip theme</h2></div><div class="table-wrap"><table><thead><tr><th>Theme</th><th>Bookings</th><th>Travellers</th></tr></thead><tbody><?php while($r=$themes->fetch_assoc()):?><tr><td><?php echo e(ucwords(str_replace('_',' ',$r['trip_theme'])));?></td><td><?php echo (int)$r['bookings'];?></td><td><?php echo (int)$r['travellers'];?></td></tr><?php endwhile;?></tbody></table></div></section>
<section class="panel"><div class="panel-head"><h2>Meal-plan performance</h2></div><div class="table-wrap"><table><thead><tr><th>Meal plan</th><th>Bookings</th><th>Travellers</th><th>Upgrade revenue</th></tr></thead><tbody><?php while($r=$mealPlans->fetch_assoc()):?><tr><td><?php echo e($r['meal_plan_name']);?></td><td><?php echo (int)$r['bookings'];?></td><td><?php echo (int)$r['travellers'];?></td><td><?php echo inr($r['upgrade_revenue']);?></td></tr><?php endwhile;?></tbody></table></div></section>
<section class="panel"><div class="panel-head"><h2>Traveller food preferences</h2></div><div class="table-wrap"><table><thead><tr><th>Preference</th><th>Travellers</th><th>Dietary notes</th></tr></thead><tbody><?php while($r=$foodPreferences->fetch_assoc()):?><tr><td><?php echo e($r['food_preference']);?></td><td><?php echo (int)$r['travellers'];?></td><td><?php echo (int)$r['dietary_notes'];?></td></tr><?php endwhile;?></tbody></table></div></section>
</div>
<?php include '_footer.php';?>
